const listSpendableCreditLots = `-- name: ListSpendableCreditLots :many
SELECT g.id, g.amount, g.ends_at,
    (g.amount - COALESCE((
        SELECT SUM(t.amount) FROM openrails.ledger_transfers t
        WHERE t.merchant_id = g.merchant_id AND t.grant_id = g.id
          AND t.transfer_type IN ('credit_spend', 'credit_expire')
    ), 0))::bigint AS remaining
FROM openrails.grants g
WHERE g.merchant_id = $1::uuid
  AND g.customer_id = $2::uuid
  AND g.kind = 'credit' AND g.event = 'grant' AND g.currency = $3::text
  AND g.starts_at <= $4::timestamptz
  AND (g.ends_at IS NULL OR g.ends_at > $4::timestamptz)
  AND NOT EXISTS (
      SELECT 1 FROM openrails.grants tt WHERE tt.supersedes_id = g.id AND tt.event IN ('revoke', 'expire', 'supersede')
  )
ORDER BY g.ends_at ASC NULLS LAST, g.created_at ASC
`

type ListSpendableCreditLotsParams struct {
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	Currency   string
	AsOf       time.Time
}

type ListSpendableCreditLotsRow struct {
	ID        uuid.UUID
	Amount    *int64
	EndsAt    *time.Time
	Remaining int64
}

// ListSpendableCreditLots: live (started, unexpired, non-terminated) credit-lot
// grants with derived remaining = lot amount − Σ(credit_spend + credit_expire
// transfers tagged to the lot). FIFO order: soonest expiry first.
func (q *Queries) ListSpendableCreditLots(ctx context.Context, arg ListSpendableCreditLotsParams) ([]ListSpendableCreditLotsRow, error) {
	rows, err := q.db.Query(ctx, listSpendableCreditLots,
		arg.MerchantID,
		arg.CustomerID,
		arg.Currency,
		arg.AsOf,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSpendableCreditLotsRow
	for rows.Next() {
		var i ListSpendableCreditLotsRow
		if err := rows.Scan(
			&i.ID,
			&i.Amount,
			&i.EndsAt,
			&i.Remaining,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listUngrantedGrantablePayments = `-- name: ListUngrantedGrantablePayments :many
SELECT p.id, p.amount, p.currency
FROM openrails.payments p
JOIN openrails.prices pr ON pr.id = p.price_id AND pr.merchant_id = p.merchant_id
JOIN openrails.products pd ON pd.id = pr.product_id AND pd.merchant_id = p.merchant_id
WHERE p.merchant_id = $1::uuid
  AND ($2::uuid IS NULL OR p.customer_id = $2::uuid)
  AND p.status = 'completed'
  AND p.amount > 0
  AND p.subscription_id IS NULL
  AND (
        (pd.entitlements_spec IS NOT NULL AND pd.entitlements_spec <> '{}'::jsonb)
     OR (pd.credits_spec IS NOT NULL AND pd.credits_spec <> '{}'::jsonb)
      )
  AND NOT EXISTS (
      SELECT 1 FROM openrails.grants g
      WHERE g.merchant_id = p.merchant_id AND g.event = 'grant'
        AND (g.payment_id = p.id OR g.source_id = p.id::text)
  )
ORDER BY p.id
`

type ListUngrantedGrantablePaymentsParams struct {
	MerchantID uuid.UUID
	CustomerID *uuid.UUID
}

type ListUngrantedGrantablePaymentsRow struct {
	ID       uuid.UUID
	Amount   int64
	Currency string
}

// #511 DERIVE `derive.grant.missing` (grant tier): a customer's completed,
// positive, one-off (non-subscription) payments for a product that PROMISES
// grants — a non-empty `entitlements_spec` or `credits_spec` — yet produced NO
// grant at all. "Paid for a grantable product, got nothing." Spec-aware (the
// positive signal is the product's own grant spec via payment→price→product), so
// empty-spec products / pure fees are never flagged; subscription payments are
// excluded (their entitlement grant is subscription-sourced, not payment-linked);
// refund rows are negative-amount (amount > 0 excludes them); a refunded purchase
// still has its `grant` event (existence, not liveness), so it is not flagged.
// Surface-only ADMIN: auto-granting re-runs derive-1 (owned by the purchase path).
// customer_id is nullable (#575): the inline customer-scoped path passes it (fast
// indexed seek); the merchant-wide convergence sweep passes NULL (one anti-join
// over the whole merchant instead of one query per grant-holder).
func (q *Queries) ListUngrantedGrantablePayments(ctx context.Context, arg ListUngrantedGrantablePaymentsParams) ([]ListUngrantedGrantablePaymentsRow, error) {
	rows, err := q.db.Query(ctx, listUngrantedGrantablePayments, arg.MerchantID, arg.CustomerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUngrantedGrantablePaymentsRow
	for rows.Next() {
		var i ListUngrantedGrantablePaymentsRow
		if err := rows.Scan(&i.ID, &i.Amount, &i.Currency); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listUnretractedTerminations = `-- name: ListUnretractedTerminations :many
SELECT g.id, g.merchant_id, g.customer_id, g.product_id, g.kind, g.source_type, g.source_id, g.payment_id, g.event, g.supersedes_id, g.spec_snapshot, g.starts_at, g.ends_at, g.amount, g.currency, g.reason, g.created_at FROM openrails.grants g
WHERE g.merchant_id = $1::uuid
  AND ($2::uuid IS NULL OR g.customer_id = $2::uuid)
  AND g.event = 'grant'
  AND EXISTS (
      SELECT 1 FROM openrails.grants t
      WHERE t.merchant_id = g.merchant_id AND t.supersedes_id = g.id
        AND t.event IN ('revoke', 'expire', 'supersede')
  )
  AND (
    (g.kind = 'entitlement' AND EXISTS (
        SELECT 1 FROM openrails.entitlements e
        WHERE e.merchant_id = g.merchant_id AND e.grant_id = g.id
          AND e.revoked_at IS NULL AND e.deleted_at IS NULL))
    OR
    (g.kind = 'credit' AND (
        g.amount - COALESCE((
            SELECT SUM(t.amount) FROM openrails.ledger_transfers t
            WHERE t.merchant_id = g.merchant_id AND t.grant_id = g.id
              AND t.transfer_type IN ('credit_spend', 'credit_expire', 'credit_revoke')
        ), 0)) > 0)
  )
ORDER BY g.created_at
`

type ListUnretractedTerminationsParams struct {
	MerchantID uuid.UUID
	CustomerID *uuid.UUID
}

// #511/#575 DERIVE `derive.grant_effect.excess` as a single set query: TERMINATED
// grants whose derived effect is still live (a revoke/expire recorded but its
// retraction never propagated). Mirrors Go IsGrantTerminated + effectStillLive —
// entitlement: a non-revoked, non-deleted entitlement row; credit: lot remainder
// (amount − spend/expire/revoke transfers) > 0. customer_id nullable: NULL =
// merchant-wide sweep. Repair = MaterializeGrant (retracts) — idempotent.
func (q *Queries) ListUnretractedTerminations(ctx context.Context, arg ListUnretractedTerminationsParams) ([]OpenrailsGrant, error) {
	rows, err := q.db.Query(ctx, listUnretractedTerminations, arg.MerchantID, arg.CustomerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OpenrailsGrant
	for rows.Next() {
		var i OpenrailsGrant
		if err := rows.Scan(
			&i.ID,
			&i.MerchantID,
			&i.CustomerID,
			&i.ProductID,
			&i.Kind,
			&i.SourceType,
			&i.SourceID,
			&i.PaymentID,
			&i.Event,
			&i.SupersedesID,
			&i.SpecSnapshot,
			&i.StartsAt,
			&i.EndsAt,
			&i.Amount,
			&i.Currency,
			&i.Reason,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const revokeEntitlementsByGrant = `-- name: RevokeEntitlementsByGrant :execrows
UPDATE openrails.entitlements
SET revoked_at = $1::timestamptz,
    revoke_reason = $2::text,
    updated_at = now()
WHERE merchant_id = $3::uuid
  AND grant_id = $4::uuid
  AND revoked_at IS NULL AND deleted_at IS NULL
`

type RevokeEntitlementsByGrantParams struct {
	RevokedAt    time.Time
	RevokeReason string
	MerchantID   uuid.UUID
	GrantID      uuid.UUID
}

func (q *Queries) RevokeEntitlementsByGrant(ctx context.Context, arg RevokeEntitlementsByGrantParams) (int64, error) {
	result, err := q.db.Exec(ctx, revokeEntitlementsByGrant,
		arg.RevokedAt,
		arg.RevokeReason,
		arg.MerchantID,
		arg.GrantID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const sumCreditGrants = `-- name: SumCreditGrants :one
SELECT COALESCE(SUM(amount), 0)::bigint
FROM openrails.grants
WHERE merchant_id = $1::uuid
  AND customer_id = $2::uuid
  AND currency = $3::text
  AND kind = 'credit' AND event = 'grant'
`

type SumCreditGrantsParams struct {
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	Currency   string
}

// SumCreditGrants: cumulative credits granted to a customer in one currency (the
// "amount paid / trust signal" that graduates the tier). Replaces SumMoneyDeposits.
func (q *Queries) SumCreditGrants(ctx context.Context, arg SumCreditGrantsParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumCreditGrants, arg.MerchantID, arg.CustomerID, arg.Currency)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}
